# 多边形基类
class Polygon:
    def __init__(self, sides):
        self.sides = sides

    def display_info(self):
        print("多边形是一个有多条边的图形")

    def get_perimeter(self):
        perimeter = sum(self.sides)
        return perimeter

# 创建四边形Quadrilateral类 
class Quadrilateral(Polygon):

    def display_info(self):
        print("四边形是一个有4条边的多边形")

# 创建Quadrilateral类对象，任意传入四条边
obj = Quadrilateral([1,2,3,4])

# 调用display_info()方法 
obj.display_info()
